INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6538951, 971925, 76335, '<td valign="top">Spurgeon''s nearby, I can feel it. Beautiful should always be this much fun.</td>', 'Spurgeon''s nearby, I can feel it. Beautiful should always be this much fun.', '2011-09-13 21:42:54.000000', NULL, 1),
(6538953, 971699, 76335, '<td valign="top">Such a stoic face to begin with. The grain has a subtractive effect. Beautifully un.</td>', 'Such a stoic face to begin with. The grain has a subtractive effect. Beautifully un.', '2011-09-13 21:47:00.000000', NULL, 1),
(6538954, 971782, 76335, '<td valign="top">Beautifully found, beautifully left.</td>', 'Beautifully found, beautifully left.', '2011-09-13 21:48:02.000000', NULL, 1),
(6538955, 971911, 66384, '<td valign="top">Eeeuuuw. Nice tone and composition. Not fond of the subject. :)</td>', 'Eeeuuuw. Nice tone and composition. Not fond of the subject. :)', '2011-09-13 21:49:29.000000', NULL, 1),
(6538956, 971899, 66384, '<td valign="top">Nice tone to go with the pretty salt.</td>', 'Nice tone to go with the pretty salt.', '2011-09-13 21:52:15.000000', NULL, 1),
(6538959, 971868, 66384, '<td valign="top">Lovely sugar-coated still life -- rich colors, beautiful light, and artistic arrangement.</td>', 'Lovely sugar-coated still life -- rich colors, beautiful light, and artistic arrangement.', '2011-09-13 21:55:38.000000', NULL, 1),
(6538963, 971664, 66384, '<td valign="top">Actually, this is duckweed. It is made up of zillions of tiny individual plants. Thus the granularity. It''s nice camouflage for the turtles, and good food for the ducks. I like your DOF on this.</td>', 'Actually, this is duckweed. It is made up of zillions of tiny individual plants. Thus the granularity. It''s nice camouflage for the turtles, and good food for the ducks. I like your DOF on this.', '2011-09-13 21:59:58.000000', NULL, 1),
(6538966, 971733, 39057, '<td valign="top">Ha...I had to look a few times. I had this idea in my head for many challenges. I never had the patience to carry it out !</td>', 'Ha...I had to look a few times. I had this idea in my head for many challenges. I never had the patience to carry it out !', '2011-09-13 22:06:08.000000', NULL, 1),
(6538979, 971746, 135937, '<td valign="top">Not only do I really like this image, I also love the subject matter. Beautiful! =) *8*</td>', 'Not only do I really like this image, I also love the subject matter. Beautiful! =) *8*', '2011-09-13 22:25:17.000000', NULL, 1),
(6538981, 971575, 135937, '<td valign="top">While I do like the concept of this photograph, it''s really soft and could use some sharpening. *6*</td>', 'While I do like the concept of this photograph, it''s really soft and could use some sharpening. *6*', '2011-09-13 22:26:39.000000', NULL, 1),
